/*eslint padding-line-between-statements: [
    "error",
    { blankLine: "always", prev: "var", next: "return" }
]*/
const CASE = {
    STATE: {
        PENDING: "-5",
        DRAFT: "1",
        CLOSED_COMPLETE: "3",
        CLOSED_INCOMPLETE: "4",
        CANCEL: "7",
        READY: "10",

        NEEDS_COMMITTEE_REVIEW: "30",

        INVESTIGATION_IN_PROGRESS: "101",
        NEEDS_OHS_ADVISOR_REVIEW: "102",
        FINAL_REVIEW_ADVISOR: "104",
        INVESTIGATION_COMPLETE_SENT_TO_ESDC: "105",
        INVESTIGATION_COMPLETE_INTERNAL: "106",
        AWAITING_EMPLOYEE: "108",
        INITIAL_REVIEW: "109",
        NEGOTIATED_RESOLUTION: "110",
        ALTERNATIVE_RESOLUTION: "112",
        MEDIATION_IN_PROGRESS: "113",

        COMPLAINT_RESOLVED_INTERNAL: "200",
        REFERRED_TO_WORKPLACE_COMMITEE: "201",
        AWAITING_MANAGER: "203",
        NEEDS_MINISTER_OF_LABOUR_REVIEW: "204",
        ISSUE_RESOLVED: "205",
        APPEALING_THE_MINISTER_OF_LABOUR_DECISION: "206",
        SENT_TO_ESDC_WAITING_FOR_INVESTIGATION_RESULT: "207",

        AWAITING_EMPLOYEE_SIGNATURE: "301",
        AWAITING_MANAGER_SIGNATURE: "302",

        RW_REVIEW: "400",

        OPEN: "900",
        IN_PROGRESS: "901",
        COMPLETED: "902",
        DRAFT_INSPECTION_REPORT: "903",
        PRELIMINARY_DISCUSSION: "904",
        NEGOTIATION_IN_PROGRESS: "905",
        REQUEST_MEDIATION: "906",
        CLOSE_UNABLE_TO_PROCESS: "907",
        MEASURES_IMPLEMENTATION_IN_PROGRESS: "908"
    }
};
var HoCOHSMUtils = Class.create();

HoCOHSMUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getWorkplaceInspectionDraft: function() {
        var param_case_sys_id = this.getParameter("sysparm_case_sys_id");
        var result = {};
        var grHrParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");

        grHrParentCase.get("sys_id", param_case_sys_id);
        var caseFound = grHrParentCase.getRowCount();

        if (caseFound === 1) {

            //result = grHrParentCase.getDisplayValue("short_description");
            result = JSON.parse(grHrParentCase.getDisplayValue("json_draft"));
            result.building = grHrParentCase.getValue("wi_building");
            result.floor_inspected = grHrParentCase.getValue("wi_floor_inspected");
            result.area_s_inspected = grHrParentCase.getValue("wi_area_inspected");
            result.date_time_of_inspection = grHrParentCase.getValue("wi_date_time_of_inspection");
            result.shared_space = grHrParentCase.getValue("wi_shared_space");
        }

        return JSON.stringify(result);
    },

    getParentOHSMDetails: function() {

        var taskId = this.getParameter("sysparm_task_num");
        var result = {};

        // Harassment and violence fields 

        result.inc_date_time = "";
        result.inc_location = "";
        result.sc_hazardous_situation = "";
        result.hazard_type = "";
        result.danger_exists = "";
        result.sc_action_plan = "";
        result.refusal_reason = "";
        result.inc_refusal_loc = "";
        result.rw_decision = "";
        result.rw_event_refusal = "";
        result.rw_corrective_action = "";
        result.rw_investigation_details = "";

        result.whsc_user = "";
        result.rw_whsc_date_time = "";
        result.rw_agree_emply_dec = "";
        result.rw_reco_deta = "";
        result.whsc_comments = "";
        result.rw_whsc_decision = "";
        result.rw_reco_empl = "";


        // Harassment and violence fields 
        result.hv_remain_anonymous = "";
        result.hv_witnesses_name = "";
        result.hv_date_of_occurence = "";
        result.hv_indiv_inv_des = "";
        result.hv_type_of_occurrence = "";
        result.hv_reviewer_request = "";
        result.hv_location_occurence = "";
        result.hv_pre_mea = "";
        result.investigation_details = "";

        // search for hr task:
        var grHrTask = new GlideRecord("sn_hr_core_task");

        grHrTask.get("sys_id", taskId);

        // find the parent case

        var grHrParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");

        grHrParentCase.get("sys_id", grHrTask.getValue("parent"));

        var caseFound = grHrParentCase.getRowCount();

        if (caseFound === 1) {
            result.inc_date_time = grHrParentCase.getDisplayValue("inc_date_time");
            result.inc_location = grHrParentCase.getDisplayValue("inc_location");
            result.sc_hazardous_situation = grHrParentCase.getDisplayValue("sc_hazardous_situation");
            result.hazard_type = grHrParentCase.getDisplayValue("hazard_type");
            result.danger_exists = grHrParentCase.getDisplayValue("danger_exists");
            result.sc_action_plan = grHrParentCase.getDisplayValue("sc_action_plan");
            result.refusal_reason = grHrParentCase.getDisplayValue("refusal_reason");
            result.inc_refusal_loc = grHrParentCase.getDisplayValue("inc_refusal_loc");
            result.rw_decision = grHrParentCase.getDisplayValue("rw_decision");
            result.rw_event_refusal = grHrParentCase.getDisplayValue("rw_event_refusal");
            result.rw_corrective_action = grHrParentCase.getDisplayValue("rw_corrective_action");
            result.rw_investigation_details = grHrParentCase.getDisplayValue("rw_investigation_details");

            result.whsc_user = grHrParentCase.getDisplayValue("whsc_user");
            result.rw_whsc_date_time = grHrParentCase.getDisplayValue("rw_whsc_date_time");
            result.rw_agree_emply_dec = grHrParentCase.getDisplayValue("rw_agree_emply_dec");
            result.rw_reco_deta = grHrParentCase.getDisplayValue("rw_reco_deta");
            result.whsc_comments = grHrParentCase.getDisplayValue("whsc_comments");
            result.rw_whsc_decision = grHrParentCase.getDisplayValue("rw_whsc_decision");
            result.rw_reco_empl = grHrParentCase.getDisplayValue("rw_reco_empl");

            // mapping harassment and violence 

            result.hv_remain_anonymous = grHrParentCase.getDisplayValue("hv_remain_anonymous");
            result.hv_witnesses_name = grHrParentCase.getDisplayValue("hv_witnesses_name");
            result.hv_date_of_occurence = grHrParentCase.getDisplayValue("hv_date_of_occurence");
            result.hv_indiv_inv_des = grHrParentCase.getDisplayValue("hv_indiv_inv_des");
            result.hv_type_of_occurrence = grHrParentCase.getDisplayValue("hv_type_of_occurrence");
            result.hv_reviewer_request = grHrParentCase.getDisplayValue("hv_reviewer_request");
            result.hv_location_occurence = grHrParentCase.getDisplayValue("hv_location_occurence");
            result.hv_pre_mea = grHrParentCase.getDisplayValue("hv_pre_mea");
            if (grHrParentCase.getValue('recipient_of_this_complaint') === 'manager') {
                result.investigation_details = grHrParentCase.getDisplayValue('rw_investigation_details');
            } else {
                result.investigation_details =
                    grHrParentCase.getDisplayValue('interim_measures_and_investigation_notes');
            }

            result.rw_minister_of_labour_decision = grHrParentCase.getDisplayValue("minister_of_labour_decision");
            result.rw_minister_of_labour_recommendations =
                grHrParentCase.getDisplayValue("minister_of_labour_recommendations");


        }

        return JSON.stringify(result);

    },

    updateParentOHSMCase: function() {
        var taskId = this.getParameter("sysparm_task_num");
        var empDecision = this.getParameter("sysparm_emp_decision"); //
        var emprefusalReason = this.getParameter("sysparm_emp_refusal_reason"); //
        var catItem = this.getParameter("sysparm_catItem");
        var result = {};

        result.updated = "";

        // search for hr task:
        var grHrTask = new GlideRecord("sn_hr_core_task");

        grHrTask.get("sys_id", taskId);

        // find the parent case
        var grHrParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");

        grHrParentCase.get("sys_id", grHrTask.getValue("parent"));

        var caseFound = grHrParentCase.getRowCount();

        if (caseFound === 1) {
            if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === 'c4d4d48d2f1fe4104cbeb1e72799b6d8'
            ) {
                grHrParentCase.setValue("emp_agree", "Yes");
                grHrParentCase.setValue("state", 106);
                // change state investigation complete - internal 106
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === 'c4d4d48d2f1fe4104cbeb1e72799b6d8'
            ) {
                grHrParentCase.setValue("emp_agree", "No");
                grHrParentCase.setValue("state", 30);
                grHrParentCase.setValue("emp_refusal_reason", emprefusalReason);
                // change state Needs Committee Review 30
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === '7763286ddbfdbc109b09e6fa4b961904'
            ) {
                grHrParentCase.setValue("emp_agree_2", "Yes");
                grHrParentCase.setValue("state", 301);
                // change state investigation complete - internal 106
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === '7763286ddbfdbc109b09e6fa4b961904'
            ) {
                grHrParentCase.setValue("emp_agree_2", "No");
                grHrParentCase.setValue("state", 301);
                grHrParentCase.setValue("emp_refusal_reason_2", emprefusalReason);
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === 'df5b84f387bdf810b7cac956cebb35c4'
            ) {
                grHrParentCase.setValue("emp_agree_3", "Yes");
                grHrParentCase.setValue("state", 205);
                // change state investigation complete - internal 106
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "internal_safety_complaint" &&
                catItem === 'df5b84f387bdf810b7cac956cebb35c4'
            ) {
                grHrParentCase.setValue("emp_agree_3", "No");
                grHrParentCase.setValue("state", 206);
                grHrParentCase.setValue("emp_refusal_reason_3", emprefusalReason);
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === '8877d9ea2f5b24104cbeb1e72799b62d'
            ) { //Refusal to work employee validation
                grHrParentCase.setValue("emp_agree", "Yes");
                grHrParentCase.setValue("state", 106);

                // change state complaint resolved - internal 200
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === '8877d9ea2f5b24104cbeb1e72799b62d'
            ) { //Refusal to work employee validation
                grHrParentCase.setValue("emp_agree", "No");
                grHrParentCase.setValue("state", 30); //
                grHrParentCase.setValue("emp_refusal_reason", emprefusalReason);
                // change state complaint resolved - internal 200
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === 'e578ccaf2fd72c104cbeb1e72799b6d2'
            ) { // Refusal to work employee validation-Stage II
                grHrParentCase.setValue("emp_agree_2", "Yes");
                grHrParentCase.setValue("state", 106);
                // change state complaint resolved - internal 200
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === 'e578ccaf2fd72c104cbeb1e72799b6d2'
            ) { //Refusal to work employee validation-Stage II
                grHrParentCase.setValue("emp_agree_2", "No");
                grHrParentCase.setValue("state", 204);
                grHrParentCase.setValue("emp_refusal_reason_2", emprefusalReason);
                // change state complaint resolved - internal 200
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === 'da183f6687d53010b7cac956cebb35b7'
            ) { //Refusal to work employee validation-Stage III
                grHrParentCase.setValue("emp_agree_3", "Yes");
                grHrParentCase.setValue("state", 205); //Issue Resolved
                grHrParentCase.setValue("emp_refusal_reason_3", emprefusalReason);
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "refusal_to_work" &&
                catItem === 'da183f6687d53010b7cac956cebb35b7') { //Refusal to work employee validation-Stage III
                grHrParentCase.setValue("emp_agree_3", "No");
                grHrParentCase.setValue("state", 206); //Appealing the Minister of Labour's decision or direction
                grHrParentCase.setValue("emp_refusal_reason_3", emprefusalReason);
            } else if (empDecision === "no" &&
                grHrParentCase.hr_service.value === "harassment_and_violence_complaint" &&
                catItem === 'cff68e8d2f67e4504cbeb1e72799b6ed') { //Harassment&Voilence stage 1
                grHrParentCase.setValue("emp_agree", "No");
                grHrParentCase.setValue("emp_refusal_reason", emprefusalReason);
            } else if (empDecision === "yes" &&
                grHrParentCase.hr_service.value === "harassment_and_violence_complaint" &&
                catItem === 'cff68e8d2f67e4504cbeb1e72799b6ed') { //Harassment&Voilence stage 1
                grHrParentCase.setValue("emp_agree", "Yes");
            }
            var resultUpdate = grHrParentCase.update();

            return resultUpdate;
        }

        return JSON.stringify(result);

    },


    updateParentOHSMCaseNew: function() {
        var taskId = this.getParameter("sysparm_task_num");
        var manDecision = this.getParameter("sysparm_emp_decision"); //
        var manrefusalReason = this.getParameter("sysparm_emp_refusal_reason"); //
        //var catItem = this.getParameter("sysparm_catItem");

        // search for hr task:
        var grHrTask = new GlideRecord("sn_hr_core_task");

        grHrTask.get("sys_id", taskId);
        // find the parent case
        var grHrParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");

        grHrParentCase.get("sys_id", grHrTask.getValue("parent"));

        var caseFound = grHrParentCase.getRowCount();

        if (caseFound === 1) {
            if (manDecision === "no") {
                grHrParentCase.setValue("man_agrees_with_result_2", "No");
                grHrParentCase.setValue("man_refusal_reason_2", manrefusalReason);
            } else {
                grHrParentCase.setValue("man_agrees_with_result_2", "Yes");
            }

            //If Employee has already signed the document, change the state accordingly
            if (grHrParentCase.getValue('sc_employee_has_signed_lab1060') === "yes") {
                if (grHrParentCase.getValue('emp_agree_2') === "Yes" && manDecision === "yes") {
                    //Change to "Investigation Complete - Internal (106)" if both (Manager and employee) did agree
                    grHrParentCase.setValue('state', 106);
                } else {
                    //Change to "Needs Minister of Labour Review (204)" 
                    //if at least one (Manager or employee) did not agree
                    grHrParentCase.setValue('state', 204);
                }
            }
        }

        var resultUpdate = grHrParentCase.update();

        return JSON.stringify(resultUpdate);

    },


    updateParentOHSMCaseHV: function() {
        var taskId = this.getParameter("sysparm_task_num");
        var empDecision = this.getParameter("sysparm_emp_decision");
        //var catItem = this.getParameter("sysparm_catItem");
        var result = {};

        result.updated = "";

        // search for hr task
        var grHrTask = new GlideRecord("sn_hr_core_task");

        grHrTask.get("sys_id", taskId);

        // find the parent case
        var grHrParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");

        grHrParentCase.get("sys_id", grHrTask.getValue("parent"));

        var caseFound = grHrParentCase.getRowCount();

        if (caseFound === 1) {
            if ((empDecision === "Yes" || empDecision === "yes") &&
                grHrParentCase.hr_service.value === "harassment_and_violence_complaint"
            ) {
                grHrParentCase.setValue(
                    "according_to_the_designated_recipient_is_it_a_harassement_and_violence_case", "Yes");
                grHrParentCase.setValue("state", 905); //Negotiation in progress
            } else {
                grHrParentCase.setValue(
                    "according_to_the_designated_recipient_is_it_a_harassement_and_violence_case", "No");
                grHrParentCase.setValue("state", 3); //Negotiation in progress
            }
            var resultUpdate = grHrParentCase.update();

            return resultUpdate;
        }

        return JSON.stringify(result);
    },

    getEmployeeAndManager: function() {
        var current_user_Sys_Id = gs.getUserID();
        var current_user_Manager = "test"; //gs.getUser().getValue("manager");

        var gr = new GlideRecord('sys_user');

        gr.addQuery('sys_id', current_user_Sys_Id);
        gr.query();
        while (gr.next()) {
            current_user_Manager = gr.getValue('manager');
        }

        var result = {
            employee: current_user_Sys_Id,
            manager: current_user_Manager
        };

        return JSON.stringify(result);
    },

    //Return the manager of an employee
    //Param: Employee sys_id
    //Return: Manager sys_id
    getManagerFromEmployee: function() {
        var current_user_Sys_Id = this.getParameter("current_user_Sys_Id");
        var current_user_Manager = "";
        var gr = new GlideRecord('sys_user');

        gr.addQuery('sys_id', current_user_Sys_Id);
        gr.query();
        while (gr.next()) {
            current_user_Manager = gr.getValue('manager');
        }
        return "" + current_user_Manager;
    },

    //Provide the sys_id of the current employee and and all its subordinates in the hierarchy
    getEmployeeAndSubordinates: function() {
        var current_user_Sys_Id = gs.getUserID();
        var listEmployee = [];

        listEmployee.push(current_user_Sys_Id);

        var gr = new GlideRecord('sys_user');

        do {
            gr.addQuery('manager', 'IN', listEmployee);
            gr.addQuery('active', 'true');
            gr.addQuery('sys_id', 'NOT IN', listEmployee);
            gr.query();
            while (gr.next()) {
                listEmployee.push(gr.getValue('sys_id'));
            }
        } while (gr.getRowCount() > 0);
        return listEmployee;
    },

    /*
        Created by: Guillaume Houde
        Created Date: 2023-06-14
        Return: returns the formatted time HHmm (not HH:mm)
        Input 1: First Parameter can be a string, a GlideRecord, a GlideElement, 
    		a GlideDateTime object and a GlideTime object 
        Input 2: Second parameter is optional, and is a string representing a GlideRecord's column
        Reference: https://www.measurethat.net/Benchmarks/Show/20813/0/...
    		...instanceof-vs-typeof-vs-objectprototypetostringcall-vs
         */
    getTime: function(recVal, grColumn) {
        if (recVal === 'undefined') { //parameter provided 
            throw new Error('Missing parameter');
        } else {
            var t;

            if (typeof recVal === 'object' &&
                (Object.prototype.toString.call(recVal).slice(8, -1) === 'ScopedGlideElement' ||
                    Object.prototype.toString.call(recVal).slice(8, -1) === 'ScopedGlideRecord') &&
                recVal.getED().getInternalType() === 'collection'
            ) {
                //if column is undefined we default to 'date_and_time_of_occurrence'
                grColumn = grColumn || 'date_and_time_of_occurrence';
                if (recVal.isValidField(grColumn)) {
                    t = new GlideDateTime(recVal.getElement(grColumn));
                } else {
                    throw new Error('Invalid column');
                }
            } else {
                t = new GlideDateTime(recVal);
            }

            //HH for 24h format, 
            //getLocalTime as it's stored in GMT 
            //no ":" because Max 4 char on the english version of LAB1070
            return t.getLocalTime().getByFormat('HHmm');
        }
    },

    /*
    Created by: Guillaume Houde
    Created Date: 2023-06-15
    Return: returns a string formatted location
    Input: a GlideRecord
     */
    getLocationString: function(gr) {
        var locationString = gr.getDisplayValue('inc_location'); //ref to cmn_location
        var street = gr.inc_location.street;
        var room = gr.getDisplayValue('inc_location_room'); //ref to cmn_location
        var area = gr.getDisplayValue('inc_location_area'); //a string
        var locationDetails = gr.getDisplayValue('inc_specific_location'); //a string

        if (street) {
            locationString += "(" + street + ")";
        }
        if (room) {
            locationString += '\n' + room;
        }
        if (area) {
            locationString += '\n' + area;
        }
        if (locationDetails) {
            locationString += '\n' + locationDetails;
        }

        return locationString;
    },

    /*
        Created by: Guillaume Houde
        Created Date: 2023-06-22
        Last update: 2023-06-28 - Guillaume Houde
        Return: an object = {input: inputString, formattedString: formattedString, inputFits: output === input}
        Input: String inputString, 
    		Integer max number of characters per line, 
    		Integer max number of lines, 
    		String what to say if it doesn't all fit
         */
    getFieldFormattedString: function(inputString, maxCharWidth, maxLines, annexString) {
        var returnObject = {
            input: inputString,
            formattedString: inputString,
            inputFits: true
        };
        var lines = [];
        var numberOfLines = 0;
        var outputString = "";
        var lastChar = 0;

        maxLines = maxLines || 1;
        annexString = annexString || "";
        //convert all "return" types to "\n" 
        //inputString = inputString.replaceAll(/\r\n/g, '\n').replaceAll(/\r/g, '\n').trim();
        inputString = inputString
            .replaceAll('\r\n', '\n')
            .replaceAll('\r', '\n')
            .trim();
        lines = inputString.split("\n");
        if (annexString.length > 0 &&
            this.getFieldFormattedString(annexString, maxCharWidth, maxLines, "").inputFits === false
        ) {
            throw new Error('Annex cannot be bigger than the field');
        }

        //if no carriage return and line fits in field, return as is.
        if (lines.length === 1 && inputString < maxCharWidth) {
            return returnObject;
        }

        for (var i = 0; i < lines.length && !outputString; i++) {
            //for(let line of lines){
            var line = lines[i];
            var linesInLine = this.getLinesInLine(line, maxCharWidth);

            //if we bust maxLines
            if (numberOfLines + linesInLine.length > maxLines) {
                var remainingLines = maxLines - numberOfLines;

                numberOfLines += remainingLines;

                for (var j = 0; j < remainingLines; j++) {
                    lastChar += linesInLine[j].length;
                }

                outputString = inputString.substring(0, lastChar - (annexString.length)) + annexString;
            } else { //we fit in maxLines
                numberOfLines += linesInLine.length;
                lastChar += line.length;

                if (inputString.charAt(lastChar) === '\n' && numberOfLines < maxLines) {
                    //there's a carriage return and there's still space
                    lastChar += 1;
                } else if (numberOfLines === maxLines && i < (lines.length - 1)) {
                    //we've reached maxLines but not the last line in input
                    var charToRemove;

                    if (linesInLine.length === 1) { //if line is 1 line
                        if (line.length + annexString.length <= maxCharWidth) { //annexString fits
                            outputString = inputString.substring(0, lastChar) + annexString;
                        } else { //annexString doesn't fit
                            charToRemove = line.length + annexString.length - maxCharWidth;
                            outputString = inputString.substring(0, lastChar - charToRemove) + annexString;
                        }
                    } else { //if line is > 1 line
                        var charsInLastLine = linesInLine.pop().length; //.pop() faster than [array.length-1]

                        if (charsInLastLine + annexString.length <= maxCharWidth) { //annexString fits
                            outputString = inputString.substring(0, lastChar) + annexString;
                        } else { //annexString doesn't fit
                            charToRemove = charsInLastLine + annexString.length - maxCharWidth;
                            outputString = inputString.substring(0, lastChar - charToRemove) + annexString;
                        }
                    }
                }
            }
        }

        if (outputString) {
            returnObject.formattedString = outputString;
            returnObject.inputFits = false;
        }

        return returnObject;
    },

    /*
    Created by: Guillaume Houde
    Created Date: 2023-06-28
    Return: an array of lines
    Input: String line (must not containt carriage return), Integer maxWidth the max number of characters per line
     */
    getLinesInLine: function(line, maxWidth) {
        var substring;
        var index;
        var lastCharProcessed = 0;
        var lines = [];

        while (lastCharProcessed + maxWidth < line.length) {
            /*
			gs.debug(
				"checking: " + 
				line.slice(0,lastCharProcessed) + 
				"[" + line.slice(lastCharProcessed, lastCharProcessed + maxWidth) + "]" + 
				line.slice(lastCharProcessed + maxWidth)
			);
			*/

            if (line.charAt(lastCharProcessed + maxWidth) === ' ') {
                lines.push(line.substring(lastCharProcessed, lastCharProcessed + maxWidth + 1));
                lastCharProcessed += maxWidth + 1;
            } else {
                substring = line.substring(lastCharProcessed, lastCharProcessed + maxWidth);
                index = substring.lastIndexOf(' ', substring.length);
                //if index = -1 then it's 1 big word that and is split in the middle, 
                //otherwise it splits after the prior space
                index = index === -1 ? substring.length : index + 1;
                lines.push(substring.substring(0, index));
                lastCharProcessed += index === 0 ? 1 : index; //prevent infinit loop 
            }
        }
        lines.push(line.substring(lastCharProcessed, lastCharProcessed + maxWidth));

        return lines;
    },

    /*
        Created by: Zachary Adams
        Created Date: 2023-07-13
        Return: returns a string for field "Did the employee receive training?"
        Input 1: a GlideRecord  
    	Input 2: Language of string(if different then english)- Optional
    	Input 3: Represents type of LAB1070 Template - 
    		"Extra" is for the Extra page templates. (Only necesary if template contains "Extra") 
         */
    getEmployeeTrainingString: function(gr, lang, type) {
        lang = lang || "en";
        type = type || '';
        if (gr.inc_training_prov === "yes" || gr.inc_training_prov === "Yes" || gr.inc_training_prov === "0") {
            if (type === 'Extra') {
                return 'doc_0_0'; //Yes
            } else {
                return gs.getMessageLang("x_hccc_hoc_ohs.Yes", lang); //Yes
            }
        } else if (type === 'Extra') {
            return 'doc_0_0'; //No
        } else {
            return gs.getMessageLang("x_hccc_hoc_ohs.Yes", lang); //No
        }
    },

