        	Created Date: 2023-07-13
        	Return: returns investigator telephone number"
        	Input1: a GlideRecord
    		Input 2: Name of investigator field wich is using the current function. 
        */
    getInvestigator: function(gr, field) {
        var value = '';

        switch (field) {
            case "number":
                if (gr.manager_name.phone.getDisplayValue() === "") {
                    value += gr.manager_name.mobile_phone.getDisplayValue();
                } else {
                    value += gr.manager_name.phone.getDisplayValue();
                }
                break;
            case "firstname":
                value += gr.manager_name.first_name;
                break;
            case "title":
                value += gr.manager_name.title;
                break;
            case "email":
                value += gr.manager_name.email;
                break;
            case "lastname":
                value += gr.manager_name.last_name;
                break;
            default:
                value = '';
        }

        return value;
    },
