    /*
    		Created by: Abigael Schonewille
    		Created Date: 2023-10-24
        	Return: returns value for pdf checkbox based on list of choices
    			Initially created for type of occurence for LAB1070Extra
        	Input 1: a GlideRecord
    		Input 2: string of the field name
    		Input 3: Choice value list 
    			(i.e for LAB1070 type of occurence option "Emergency Procedure", input 2 would be "emerg_proc")
        */
    getPDFCheckboxValue: function(gr, check_field, choice_list) {
        var choice_check_value = '';

        for (var i = 0; i < choice_list.length; i++) {
            if (gr.getValue(check_field) === choice_list[i]) {
                choice_check_value = 'Yes';
                return choice_check_value;
            }
        }
        return choice_check_value;
    },

    /*
    		Created by: Abigael Schonewille
    		Created Date: 2023-10-25
        	Return: returns value for choice list in specified language
    			Initially created for type of occurence for LAB1070Extra
        	Input 1: table the choice list is from
    		Input 2: value of the desired choice
    		Input 3: language to return the choice label in
        */
    getChoiceTranslation: function(table, choice_value, lang) {

        if (lang !== 'en' && lang !== 'fq') {
            lang = 'en';
        }

        var grChoice = new GlideRecord('sys_choice');

        grChoice.addQuery('name', table);
        grChoice.addQuery('value', choice_value);
        grChoice.addQuery('language', lang);

        grChoice.query();

        if (grChoice.next()) {
            return grChoice.getDisplayValue();
        }

        return '';
    },

    /*
    		Created by: Abigael Schonewille
    		Created Date: 2023-10-24
        	Return: returns value for pdf other specify field
    			Initially created for type of occurence for LAB1070Extra
        	Input 1: a GlideRecord
    		Input 2: string of the field name with other
    		Input 3: string of the field name that specifies other
    		Input 4: Choice value list 
    			(i.e for LAB1070 type of occurence option "Emergency Procedure", input 2 would be "emerg_proc")
        */
    getPDFSpecifyOtherValue: function(gr, check_field, specify_field, choice_list) {
        var specify_field_value = '';

        for (var i = 0; i < choice_list.length; i++) {
            if (gr.getValue(check_field) === choice_list[i]) {
                if (choice_list[i] === 'other') {
                    specify_field_value = gr.getDisplayValue(specify_field);
                } else {

                    var check_field_choice_table = "";
                    var grDict = new GlideRecord('sys_dictionary');

                    grDict.addQuery('name', gr.sys_class_name);
                    grDict.addQuery('element', check_field);
                    grDict.query();

                    if (grDict.next()) {
                        check_field_choice_table = grDict.choice_table;
                    }

                    var choice_value = gr.getValue(check_field);
                    var manager_lang = gr.manager_name.preferred_language.toString();

                    specify_field_value = this.getChoiceTranslation(check_field_choice_table, choice_value, manager_lang);
                }
                return specify_field_value;
            }
        }
        return specify_field_value;
    },

    /*
    		Created by: Marcus Martinet
    		Created Date: 2024-03-07
        	Return: returns Corrective Measure with Implementation Date
    			Input1: Workplace Incident Reporting case
    			Input2: Corrective Measure field name
    			Input3: Implementation Date field name
        */
    getMeasuresAndDate: function(caseGr, CorrectiveMeasures, ImplementationDate) {
        var MeasuresAndDate = "";

        if (caseGr.getValue(ImplementationDate) === null || caseGr.getValue(ImplementationDate) === '') {
            MeasuresAndDate = caseGr.getValue(CorrectiveMeasures);
            return MeasuresAndDate;
        } else if (caseGr.getValue(ImplementationDate) != null && caseGr.getValue(ImplementationDate) != null) {
            MeasuresAndDate = caseGr.getValue(CorrectiveMeasures) + " (" + caseGr.getValue(ImplementationDate) + ")";
            return MeasuresAndDate;
        }

        return MeasuresAndDate;
    },

    /*
    		Created by: Abigael Schonewille
    		Created Date: 2023-11-07
        	Return: returns specified value from json draft data for LAB 1009 and LAB 1058 
    			PDF template mapping
        	Input 1: OHSM glide record containing the staged json draft data
    		Input 2: string of the target field 
    		Input 3: index for the desired value in the target field
        */
    getPDFMappingFromJSONDraft: function(gr, target_field, target_index) {
        gs.info('OHSM Testing: ' + gs.json_draft);
        var stageData = JSON.parse(gr.json_draft);

        var target_value = "";
        var str = "";

        if (target_field === "Address") {
            str = stageData.addr;
        } else if (target_field === "Comment") {
            str = stageData.comment;
        }

        var arr = [];

        arr = str.split(',');

        if (target_index >= arr.length) {
            return ''
        }

        target_value = arr[target_index];

        if (target_field === 'Comment') {
            var bldgName_str = stageData.bldgName;
            var bldgName_arr = bldgName_str.split(',');
            var bldgName = bldgName_arr[target_index];

            target_value = bldgName + ". " + target_value;
        }

        return target_value;

    },

    /*
    	Created by: Abigael Schonewille
    	Created Date: 2023-11-20
        	Return: get the appropriate LAB 1009 and LAB 1058 pdf templates based on the user's language
        */
    getReportChoiceList: function() {
        var current_lang = gs.getSession().getLanguage();
        var admin_permission = gs.hasRole('x_hccc_hoc_ohs.admin');
        var advisor_permission = gs.hasRole('x_hccc_hoc_ohs.advisor');
        var committee_permission = gs.hasRole('x_hccc_hoc_ohs.committee');

        if (current_lang === 'en') {
            if (admin_permission || advisor_permission) {
                return "nameNOT LIKEold^nameLIKElab^nameLIKEEN^nameLIKE1009^ORnameLIKE1058^ORnameLIKE1206";
            } else if (committee_permission) {
                return "nameNOT LIKEold^nameLIKElab^nameLIKEEN^nameLIKE1058";
            } else {
                return 'name=none';
            }
        } else if (current_lang === 'fq') {
            if (admin_permission || advisor_permission) {
                return "nameNOT LIKEold^nameLIKElab^nameLIKEFQ^nameLIKE1009^ORnameLIKE1058^ORnameLIKE1206";
            } else if (committee_permission) {
                return "nameNOT LIKEold^nameLIKElab^nameLIKEFQ^nameLIKE1058";
            } else {
                return 'name=none';
            }
        } else {
            return 'name=none';
        }
    },

    /*
    	Created by: Abigael Schonewille
    	Created Date: 2023-12-12
        	Return: get list of buildings committee members have access for to produce LAB 1058
        */
    getApprovedCommitteeBuildings: function() {
        var admin_permission = gs.hasRole('x_hccc_hoc_ohs.admin');
        var advisor_permission = gs.hasRole('x_hccc_hoc_ohs.advisor');
        var committee_permission = gs.hasRole('x_hccc_hoc_ohs.committee');

        if (admin_permission || advisor_permission) {
            return "";
        } else if (committee_permission) {

            var current_user = gs.getUserID();
            var user_groups_gr = new GlideRecord('sys_user_grmember');

            user_groups_gr.addQuery('user', current_user);
            user_groups_gr.addEncodedQuery('groupSTARTSWITHCEH-HRS-OHS-COMMITTEE');
            user_groups_gr.query();

            var building_query = '';
            var address = '';
            var current_building = '';

            while (user_groups_gr.next()) {

                var building_list = user_groups_gr.group.description.split(", ");

                for (let i = 0; i < building_list.length; i++) {
                    current_building = building_list[i].split(" (");

                    [address] = current_building;

                    if (i !== 0) {
                        building_query = building_query + '^NQ';
                    }

                    building_query = building_query + 'streetLIKE' + address;
                }
            }
            return building_query;
        } else {
            return 'name=none';
        }
    },

    /*
    	Created by: Abigael Schonewille
    	Created Date: 2023-12-19
        	Return: true or false based on if user has permission to access a given lab 1058 record
        */
    getCommitteeRecordPermissions: function(admin_or_advisor_permission, committee_permission, current_user, report_building) {

        if (admin_or_advisor_permission) {
            return true;
        } else if (committee_permission) {
            var user_groups_gr = new GlideRecord('sys_user_grmember');

            user_groups_gr.addQuery('user', current_user);
            user_groups_gr.addEncodedQuery('groupSTARTSWITHCEH-HRS-OHS-COMMITTEE');
            user_groups_gr.query();

            var address = '';
            var current_building = '';
            var building_permission = false;

            while (user_groups_gr.next()) {
                var building_list = user_groups_gr.group.description.split(", ");

                for (let i = 0; i < building_list.length; i++) {
                    current_building = building_list[i].split(" (");

                    [address] = current_building;

                    var correct_building = report_building.street.includes(address);

                    building_permission = building_permission || correct_building;

                }
            }

            if (building_permission) {
                return true;
            } else {
                return false;
            }

        } else {
            return false;
        }
    },

