    /*
       	Created by: Abigael Schonewille
       	Created Date: 2024-07-10
    	Description: Create a list of H&V records based on the current user's access permissions for use in reports
       	Return: a list of sys ids
       	Input: a user record, a string of the group name
    */
    hvReportRecords: function() {
        var hv_records_gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');

        hv_records_gr.addQuery('hr_service', '11d78aa31bb201509fde86acdd4bcb0b'); //hr service is harassment and violence
        hv_records_gr.addEncodedQuery('stateIN109,900'); //state is initial review or open
        hv_records_gr.query();

        var current_user = gs.getUserID();


        var all_records = false;
        var hv_records_sys_id_list = [];

        while (hv_records_gr.next()) {
            var include_record = false;

            if (all_records) {

                include_record = true;

            } else if (hv_records_gr.getValue('assigned_to') === current_user) { //manager

                include_record = true;

            } else { //OHS Admin, OHS Advisors, OHS RW, WHSC committee
                var user_groups_gr = new GlideRecord('sys_user_grmember');

                user_groups_gr.addQuery('user', current_user); //current user
                user_groups_gr.query();

                while (user_groups_gr.next() && !all_records && !include_record) {

                    if (user_groups_gr.getValue('group') === "f825414a2f4f68904cbeb1e72799b6bb" || user_groups_gr.getValue('group') === "13e4414a2f4f68904cbeb1e72799b6f1" || user_groups_gr.getValue('group') === "b4a1b2c2db927c109b09e6fa4b961983") { //OHS Admin, OHS Advisors, OHS RW

                        all_records = true;
                        include_record = true;
                    } else if (user_groups_gr.getValue('group') === hv_records_gr.complainant_name.location.u_hs_committee.sys_id.toString()) {

                        include_record = true;
                    }
                }
            }
            if (include_record) {
                hv_records_sys_id_list.push(hv_records_gr.sys_id.toString());
            }
        }

        return hv_records_sys_id_list;
    },

    /*
       	Created by: Abigael Schonewille
       	Created Date: 2024-08-02
    	Description: check current user's permission to use the initial review ui action for the HV module
       	Return: true/false to represent permission or not
    */
    hvInitReviewActionPerm: function(state, hr_service, assigned_to) {
        //gs.info("OHSM Testing: init review ui action - " + state + "/" + hr_service + "/" + assigned_to);
        var permission = false;

        if (state.toString() === '109' && hr_service.toString() === 'harassment_and_violence_complaint') {

            if (gs.getUser().isMemberOf("CEH-HRS-OHS-Respectful Workplace")) {
                permission = true;
            } else if (gs.getUser().getID() === assigned_to) {
                permission = true;
            }
        }
        return permission;
    },

