        //gs.info("OHSM Testing: close case ui action - " + state + "/" + hr_service + "/" + assigned_to + "/" + investigation_start);
        var permission = false;

        if ((state.toString() === '109' || state.toString() === '900') && hr_service.toString() === 'harassment_and_violence_complaint') {

            if (gs.getUser().isMemberOf("CEH-HRS-OHS-Respectful Workplace")) {
                permission = true;
