    /*
       	Created by: Abigael Schonewille
       	Created Date: 2025-09-24
    	Description: check current user's permission to access the attachments icon for HV cases
       	Return: JSON with true/false to represent permission to access or not
    */
    getHVAttachmentIconPermissions: function() {
        var case_id = this.getParameter("sysparm_case_id");
        var result = {};

        result.hv_attachment_permission = this.checkHVAttachmentPermissions(case_id);
        return JSON.stringify(result);
    },

    /*
       	Created by: Abigael Schonewille
       	Created Date: 2025-09-24
    	Description: check current user's permission to access the attachments for HV cases
		Input: case_id - sys_id of the hv case being opened
       	Return: true/false to represent permission to access or not
    */
    checkHVAttachmentPermissions: function(case_id) {
        var result = false;

        if (gs.getUser().isMemberOf("CEH-HRS-OHS-Respectful Workplace")) {
            //check if user in RW group
            result = true;

        } else if (gs.getUser().isMemberOf("CEH-HRS-OHS-Admin")) {
            //check if user in OHS admin group
            result = true;

        } else { //check if user is manager handling the case
            var hv_case_gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');

            hv_case_gr.addQuery('sys_id', case_id);
            hv_case_gr.query();

            if (hv_case_gr.next()) {
                var user_id = gs.getUser().getID();

                if (user_id.toString() === hv_case_gr.assigned_to.toString() && user_id.toString() === hv_case_gr.hv_complainant_manager.toString() && hv_case_gr.getValue('manager_involved') === 'yes') {
                    result = true;
                }
            }
        }
        return result;
    },


    type: 'HoCOHSMUtils'
